from typing import Final


SCRIPT_TEMPLATE: Final[str] = '''#!/usr/bin/env python3
"""Local extraction of this folder. Generated by simplibs-extractor.

Run it with:  python {file_name}
"""
from simplibs.extractor import extract_here

if __name__ == "__main__":
    extract_here(__file__, profile={profile!r})
'''
"""The text of a generated local script; `{file_name}` and `{profile}` are filled in."""


_DESIGN_NOTES = """
# SCRIPT_TEMPLATE — Three Lines of Logic

## Purpose
A script a person can drop into any project folder. It contains no path and no
configuration: `extract_here(__file__, ...)` takes the folder from where the
script lies.

## Why a `__main__` Guard
Importing the script (a test, an editor's indexer) must not start an
extraction.

## `{profile!r}`
The profile key is written as a Python literal, quotes included, so a key
can never break the generated code.
"""
